import { db, newEnvelope } from './db'
import type { EventType, Profile } from '@/types/domain'

/**
 * Sample data — "what does this look like after a couple has actually used it?"
 *
 * An empty app is impossible to judge. Every screen shows its empty state, so
 * you cannot tell whether the money space is any good, or whether the mental
 * load split reads as fair. This fills roughly six months of ordinary
 * Indonesian household life so the product can be seen rather than imagined.
 *
 * Three rules it follows, because a demo that breaks them teaches the wrong
 * thing about the product:
 *
 *  1. Every record goes through `newEnvelope`, exactly like real data. No
 *     hand-built envelopes, so visibility defaults apply — the cycle log below
 *     is private because the envelope makes it private, not because the demo
 *     remembered to be careful.
 *  2. Nothing is a "score". No entry implies one partner is better.
 *  3. Every record is tagged `demo: true` so `clearDemo()` can remove exactly
 *     these and leave anything real untouched.
 *
 * Deliberately NOT seeded: pregnancy, fertility and co-parenting records.
 * Filling a couple's app with a pregnancy they do not have is a bad surprise,
 * and the loss-mode screens exist precisely because that subject deserves care.
 *
 * Lives in `db/` rather than the settings feature on purpose: like `backup.ts`
 * and `unpair.ts`, it legitimately walks whole stores, which feature code is
 * not allowed to do.
 */

/** Marks a record as demo so it can be removed again without guesswork. */
const DEMO = { demo: true } as const

function iso(daysAgo: number): string {
  const d = new Date()
  d.setDate(d.getDate() - daysAgo)
  return d.toISOString().slice(0, 10)
}

function ahead(days: number): string {
  return iso(-days)
}

/** True when the sample data is currently loaded. */
export async function hasDemo(): Promise<boolean> {
  const row = await db.settings.get('demo.loaded')
  return row?.value === true
}

export async function loadDemo(me: Profile, partner: Profile | undefined): Promise<void> {
  const mine = me.id
  // Without a second profile the demo still works — it just reads as one
  // person's household rather than two.
  const theirs = partner?.id ?? me.id

  const checkins = [2, 5, 9, 13, 18, 24, 31, 40].map((d, i) => ({
    ...newEnvelope(i % 2 === 0 ? mine : theirs, 'C3_relationship'),
    ...DEMO,
    kind: 'checkin' as const,
    date: iso(d),
    energy: ([3, 4, 2, 4, 5, 3, 4, 3] as const)[i]!,
    connection: ([4, 4, 3, 5, 5, 4, 4, 4] as const)[i]!,
    note: [
      'Capek kerjaan tapi seneng bisa makan malem bareng.',
      'Ngobrol lama soal rencana tahun depan.',
      'Lagi banyak deadline, agak jarang ngobrol.',
      'Nonton film di rumah, santai.',
      'Weekend ke rumah ibu, ramai tapi hangat.',
      undefined,
      'Beres-beres gudang bareng, ternyata seru.',
      undefined,
    ][i],
  }))

  const needs = [
    { text: 'Pengen kita punya satu malam seminggu yang bener-bener nggak megang HP.', owner: mine, days: 12 },
    { text: 'Kadang aku butuh didengerin dulu sebelum dikasih solusi.', owner: mine, days: 30 },
    { text: 'Aku pengen lebih sering diajak ngobrol soal keputusan besar.', owner: theirs, days: 21 },
  ].map((n) => ({
    ...newEnvelope(n.owner, 'C3_relationship'),
    ...DEMO,
    kind: 'need' as const,
    text: n.text,
    createdAt: new Date(Date.now() - n.days * 864e5).toISOString(),
  }))

  const appreciations = [
    { text: 'Makasih udah bangun pagi buat nyiapin sarapan waktu aku telat.', owner: theirs, days: 4 },
    { text: 'Kamu sabar banget waktu aku lagi bad mood kemarin.', owner: mine, days: 11 },
    { text: 'Makasih udah urus BPJS-nya sampai kelar.', owner: mine, days: 26 },
  ].map((a) => ({
    ...newEnvelope(a.owner, 'C3_relationship'),
    ...DEMO,
    kind: 'appreciation' as const,
    text: a.text,
    sentAt: new Date(Date.now() - a.days * 864e5).toISOString(),
  }))

  const topics = [
    { title: 'Rencana pindah kontrakan tahun depan', status: 'open' as const },
    { title: 'Batasan bantuin keuangan keluarga besar', status: 'scheduled' as const },
    { title: 'Pembagian tugas kalau nanti ada anak', status: 'parked' as const },
    { title: 'Liburan akhir tahun ke mana', status: 'talked' as const },
  ].map((t) => ({
    ...newEnvelope(mine, 'C3_relationship'),
    ...DEMO,
    kind: 'topic' as const,
    title: t.title,
    status: t.status,
  }))

  // Typed up front: without the annotation the array's element type is a union
  // of "has time" and "has no time" shapes, which Dexie's InsertType rejects.
  const eventSeeds: { title: string; date: string; type: EventType; time?: string }[] = [
    { title: 'Kondangan Mbak Rani', date: ahead(6), type: 'family', time: '11:00' },
    { title: 'Bayar listrik & air', date: ahead(2), type: 'bill' },
    { title: 'Kontrol gigi', date: ahead(13), type: 'health', time: '16:30' },
    { title: 'Anniversary kita', date: ahead(28), type: 'celebration' },
    { title: 'Arisan RT', date: ahead(9), type: 'family', time: '19:30' },
    { title: 'Ulang tahun Ibu', date: ahead(17), type: 'family' },
  ]
  const events = eventSeeds.map((e) => ({
    ...newEnvelope(mine, 'C2_shared_ops'),
    ...DEMO,
    kind: 'event' as const,
    ...e,
  }))

  // The point of the household model: who *notices* and who *plans*, not just
  // who does. A demo where every task is 'do' teaches the opposite.
  const tasks = [
    { title: 'Bayar tagihan bulanan', who: mine, load: 'remember' as const, status: 'done' as const },
    { title: 'Stok dapur menipis — cek dulu', who: theirs, load: 'notice' as const, status: 'todo' as const },
    { title: 'Atur jadwal servis motor', who: theirs, load: 'coordinate' as const, status: 'doing' as const },
    { title: 'Rencanain menu seminggu', who: mine, load: 'plan' as const, status: 'todo' as const },
    { title: 'Cuci gorden', who: theirs, load: 'do' as const, status: 'done' as const },
    { title: 'Urus perpanjangan STNK', who: mine, load: 'coordinate' as const, status: 'todo' as const },
    { title: 'Beli kado buat keponakan', who: theirs, load: 'remember' as const, status: 'todo' as const },
  ].map((t, i) => ({
    ...newEnvelope(t.who, 'C2_shared_ops'),
    ...DEMO,
    kind: 'task' as const,
    title: t.title,
    accountableProfileId: t.who,
    helperProfileIds: [],
    mentalLoadType: t.load,
    status: t.status,
    completedAt: t.status === 'done' ? new Date().toISOString() : undefined,
    // Spread across the next fortnight so the list is not one wall of the same
    // date. Deterministic — a demo that reshuffles on every load is impossible
    // to screenshot or compare against.
    dueDate: ahead(3 + i * 2),
  }))

  const bills = [
    { title: 'Kontrakan', amount: 1_800_000, space: 'shared' as const, status: 'paid' as const, due: iso(4) },
    { title: 'Listrik token', amount: 250_000, space: 'shared' as const, status: 'unpaid' as const, due: ahead(2) },
    { title: 'Internet', amount: 350_000, space: 'shared' as const, status: 'paid' as const, due: iso(9) },
    { title: 'Cicilan motor', amount: 950_000, space: 'shared' as const, status: 'unpaid' as const, due: ahead(11) },
    { title: 'Paket data', amount: 100_000, space: 'mine' as const, status: 'paid' as const, due: iso(6) },
  ].map((b) => ({
    ...newEnvelope(mine, 'C2_shared_ops'),
    ...DEMO,
    kind: 'bill' as const,
    title: b.title,
    amount: b.amount,
    currency: 'IDR' as const,
    dueDate: b.due,
    payerProfileId: mine,
    splitModel: 'equal' as const,
    status: b.status,
    paidAt: b.status === 'paid' ? new Date().toISOString() : undefined,
    space: b.space,
  }))

  const memories = [
    { title: 'Pertama kali masak rendang bareng', date: iso(52), milestone: false, story: 'Gosong dikit tapi tetep dimakan.' },
    { title: 'Anniversary tahun ini', date: iso(96), milestone: true, story: 'Makan di tempat yang sama kayak pertama kali ketemu.' },
    { title: 'Liburan ke Dieng', date: iso(140), milestone: true, story: 'Dingin banget, tapi sunrise-nya worth it.' },
    { title: 'Pindahan ke kontrakan sekarang', date: iso(180), milestone: true },
    { title: 'Nemenin dia sidang', date: iso(74), milestone: false },
  ].map((m) => ({
    ...newEnvelope(mine, 'C2_shared_ops'),
    ...DEMO,
    kind: 'memory' as const,
    title: m.title,
    date: m.date,
    story: m.story,
    isMilestone: m.milestone,
  }))

  const groceries = ['Beras 5kg', 'Minyak goreng', 'Telur', 'Kopi bubuk', 'Sabun cuci piring'].map(
    (name, i) => ({
      ...newEnvelope(i % 2 === 0 ? mine : theirs, 'C2_shared_ops'),
      ...DEMO,
      kind: 'grocery' as const,
      name,
      bought: i < 2,
      boughtAt: i < 2 ? new Date().toISOString() : undefined,
    }),
  )

  // Health data. Private by DEFAULT_VISIBILITY, not by anything written here —
  // that is the whole point of routing the demo through newEnvelope.
  const cycles = [0, 29, 58].map((d) => ({
    ...newEnvelope(mine, 'C4_health'),
    ...DEMO,
    kind: 'cycle' as const,
    startDate: iso(d + 3),
    durationDays: 5,
    symptoms: d === 0 ? ['kram', 'capek'] : ['capek'],
    energy: 3 as const,
    supportPreference: 'Dua hari pertama aku lebih butuh istirahat, bukan diajak keluar.',
  }))

  await db.transaction(
    'rw',
    [db.checkins, db.needs, db.appreciations, db.topics, db.events, db.tasks, db.bills, db.memories, db.groceries, db.cycles, db.settings],
    async () => {
      await db.checkins.bulkAdd(checkins)
      await db.needs.bulkAdd(needs)
      await db.appreciations.bulkAdd(appreciations)
      await db.topics.bulkAdd(topics)
      await db.events.bulkAdd(events)
      await db.tasks.bulkAdd(tasks)
      await db.bills.bulkAdd(bills)
      await db.memories.bulkAdd(memories)
      await db.groceries.bulkAdd(groceries)
      await db.cycles.bulkAdd(cycles)
      await db.settings.put({ key: 'demo.loaded', value: true })
    },
  )
}

/**
 * Removes only what `loadDemo` added.
 *
 * Filtering on the `demo` flag rather than clearing the tables is what makes
 * this safe to run on an app that already holds real entries — someone who
 * tried the sample data and then started using the app for real must not lose
 * their own records.
 */
export async function clearDemo(): Promise<void> {
  // Addressed by NAME rather than by table object: the tables have different
  // row types, so a plain array of them is a union TypeScript cannot call
  // `bulkDelete` on. `db.table(name)` hands back a uniform handle, and the
  // names are the same ones `loadDemo` wrote to.
  const names = [
    'checkins', 'needs', 'appreciations', 'topics',
    'events', 'tasks', 'bills', 'memories', 'groceries', 'cycles',
  ] as const

  await db.transaction('rw', [...names.map((n) => db.table(n)), db.settings], async () => {
    for (const name of names) {
      const table = db.table<{ id: string; demo?: true }>(name)
      const ids = (await table.toArray()).filter((r) => r.demo === true).map((r) => r.id)
      if (ids.length) await table.bulkDelete(ids)
    }
    await db.settings.delete('demo.loaded')
  })
}
