import { useEffect, useState } from 'react'
import { Card, Field } from '@/components/ui'
import { Icon } from '@/design-system/Icon'
import { useI18n } from '@/i18n'
import { clearPin, hasPin, isPinShaped, setPin, verifyPin } from './pin'

/**
 * Turning the lock on, changing it, taking it off — all behind the current PIN.
 *
 * Removing or changing the PIN without knowing it would make the lock a
 * decoration: anyone holding the unlocked phone could quietly disarm it and
 * hand it back. So every mutation except the very first asks for the current
 * PIN first, and the warning about no recovery is shown before the first PIN
 * is set — the one moment the person can still choose a number they will
 * remember.
 */
export function LockSettings() {
  const { t } = useI18n()
  const [enabled, setEnabled] = useState<boolean | null>(null)
  const [editing, setEditing] = useState(false)
  const [current, setCurrent] = useState('')
  const [next, setNext] = useState('')
  const [repeat, setRepeat] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [notice, setNotice] = useState<string | null>(null)

  useEffect(() => {
    void hasPin().then(setEnabled)
  }, [])

  if (enabled === null) return null

  function reset() {
    setEditing(false)
    setCurrent('')
    setNext('')
    setRepeat('')
    setError(null)
  }

  async function save() {
    setError(null)
    if (enabled && !(await verifyPin(current))) {
      setError(t('set.lockWrongCurrent'))
      return
    }
    if (!isPinShaped(next)) {
      setError(t('set.lockNew'))
      return
    }
    if (next !== repeat) {
      setError(t('set.lockMismatch'))
      return
    }
    await setPin(next)
    setEnabled(true)
    setNotice(t('set.lockSaved'))
    reset()
  }

  async function remove() {
    setError(null)
    if (!(await verifyPin(current))) {
      setError(t('set.lockWrongCurrent'))
      return
    }
    await clearPin()
    setEnabled(false)
    setNotice(t('set.lockRemoved'))
    reset()
  }

  return (
    <Card title={t('set.lockTitle')} icon="shield" hint={t('set.lockHint')}>
      <div className="stack stack--tight">
        {notice && (
          <p className="banner" role="status">
            <Icon name="info" size={18} /> {notice}
          </p>
        )}
        {error && (
          <p className="banner banner--danger" role="alert">
            {error}
          </p>
        )}

        {!editing ? (
          <button type="button" className="btn btn--soft" onClick={() => { setNotice(null); setEditing(true) }}>
            <Icon name="shield" size={18} />
            {enabled ? t('set.lockChange') : t('set.lockOn')}
          </button>
        ) : (
          <>
            {/* The one moment to say it: before the first PIN exists. */}
            {!enabled && <p className="banner banner--warn">{t('set.lockWarn')}</p>}

            {enabled && (
              <Field label={t('set.lockCurrent')}>
                {(p) => (
                  <input
                    {...p}
                    type="password"
                    inputMode="numeric"
                    maxLength={6}
                    autoComplete="off"
                    value={current}
                    onChange={(e) => setCurrent(e.target.value.replace(/\D/g, ''))}
                  />
                )}
              </Field>
            )}
            <Field label={t('set.lockNew')}>
              {(p) => (
                <input
                  {...p}
                  type="password"
                  inputMode="numeric"
                  maxLength={6}
                  autoComplete="off"
                  value={next}
                  onChange={(e) => setNext(e.target.value.replace(/\D/g, ''))}
                />
              )}
            </Field>
            <Field label={t('set.lockRepeat')}>
              {(p) => (
                <input
                  {...p}
                  type="password"
                  inputMode="numeric"
                  maxLength={6}
                  autoComplete="off"
                  value={repeat}
                  onChange={(e) => setRepeat(e.target.value.replace(/\D/g, ''))}
                />
              )}
            </Field>
            <div className="row" style={{ gap: 'var(--space-2)', flexWrap: 'wrap' }}>
              <button type="button" className="btn" disabled={!isPinShaped(next)} onClick={() => void save()}>
                <Icon name="check" size={18} />
                {t('common.save')}
              </button>
              {enabled && (
                <button type="button" className="btn btn--danger" disabled={!isPinShaped(current)} onClick={() => void remove()}>
                  {t('set.lockOff')}
                </button>
              )}
              <button type="button" className="btn btn--ghost" onClick={reset}>
                {t('common.cancel')}
              </button>
            </div>
          </>
        )}
      </div>
    </Card>
  )
}
