import { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import PairPanel from '@/features/sync/PairPanel'
import { Icon } from '@/design-system/Icon'
import { Card, Field, Sheet } from '@/components/ui'
import { useSession } from '@/app/session'
import { STAGE_DESC, STAGE_LABEL } from '@/app/nav'
import { wipeDevice } from '@/db/db'
import { LockSettings } from '@/features/applock/LockSettings'
import { clearDemo, hasDemo, loadDemo } from '@/db/demoData'
import { importPack } from '@/features/calendar/holidays'
import { STAGES, type Stage } from '@/types/domain'
import { LOCALES, LOCALE_LABEL, useI18n } from '@/i18n'
import { THEMES, THEME_HINT, THEME_LABEL, THEME_SWATCH, useTheme } from '@/app/theme'

export default function Settings() {
  const { t, locale, setLocale } = useI18n()
  const { theme, setTheme } = useTheme()
  const [demoOn, setDemoOn] = useState(false)
  const [demoBusy, setDemoBusy] = useState(false)
  const { profile, profiles, setStage, createProfile, refresh } = useSession()
  const [message, setMessage] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [confirmWipe, setConfirmWipe] = useState(false)
  const [wipeText, setWipeText] = useState('')
  const [newProfileName, setNewProfileName] = useState('')
  const [updateReady, setUpdateReady] = useState<null | (() => void)>(null)

  // The service worker never swaps itself in silently (blueprint 06 §3).
  useEffect(() => {
    function onUpdate(e: Event) {
      const detail = (e as CustomEvent<{ updateSW: (reload?: boolean) => void }>).detail
      setUpdateReady(() => () => detail.updateSW(true))
    }
    window.addEventListener('temudua:update-ready', onUpdate)
    return () => window.removeEventListener('temudua:update-ready', onUpdate)
  }, [])

  useEffect(() => {
    void hasDemo().then(setDemoOn)
  }, [])

  if (!profile) return null

  async function addDemo() {
    if (!profile) return
    setDemoBusy(true)
    setError(null)
    try {
      await loadDemo(profile, profiles.find((p) => p.id !== profile.id))
      setDemoOn(true)
      setMessage(t('demo.loaded'))
    } catch {
      setError(t('demo.failed'))
    } finally {
      setDemoBusy(false)
    }
  }

  async function removeDemo() {
    setDemoBusy(true)
    setError(null)
    try {
      await clearDemo()
      setDemoOn(false)
      setMessage(t('demo.removed'))
    } catch {
      setError(t('demo.failed'))
    } finally {
      setDemoBusy(false)
    }
  }

  async function wipe() {
    await wipeDevice()
    window.location.reload()
  }

  return (
    <div className="stack">
      <h1>{t('set.title')}</h1>

      {message && (
        <p className="banner" role="status">
          <Icon name="info" size={18} /> {message}
        </p>
      )}
      {error && (
        <p className="banner banner--danger" role="alert">
          {error}
        </p>
      )}

      {updateReady && (
        <Card title={t('set.updateReady')} icon="restore" hint={t('set.updateHint')}>
          <button className="btn btn--block" onClick={updateReady}>{t('set.updateNow')}
          </button>
        </Card>
      )}

      <Card title={t('set.stage')} icon="heart" hint={t('set.stageHint')}>
        <div className="choices" role="radiogroup" aria-label={t('set.stage')}>
          {STAGES.map((s: Stage) => (
            <button
              key={s}
              type="button"
              role="radio"
              aria-checked={profile.stage === s}
              className="choice"
              onClick={() => setStage(s)}
            >
              <span className="stack stack--tight">
                <span className="choice__title">{t(STAGE_LABEL[s])}</span>
                <span className="choice__desc">{t(STAGE_DESC[s])}</span>
              </span>
            </button>
          ))}
        </div>
        {profile.stageHistory.length > 1 && (
          <p className="card__hint" style={{ marginTop: 'var(--space-2)' }}>
            {t('set.stageChanges', { n: profile.stageHistory.length - 1 })}
          </p>
        )}
      </Card>

      <Card title={t('theme.title')} icon="date" hint={t('theme.hint')}>
        <div className="theme-grid" role="radiogroup" aria-label={t('theme.title')}>
          <button
            type="button"
            role="radio"
            aria-checked={theme === null}
            className="theme-tile"
            onClick={() => setTheme(null)}
          >
            <span className="theme-tile__swatch theme-tile__swatch--auto" aria-hidden="true" />
            <span className="theme-tile__name">{t('theme.system')}</span>
            <span className="theme-tile__hint">{t('theme.systemHint')}</span>
          </button>
          {THEMES.map((th) => (
            <button
              key={th}
              type="button"
              role="radio"
              aria-checked={theme === th}
              className="theme-tile"
              onClick={() => setTheme(th)}
            >
              <span className="theme-tile__swatch" aria-hidden="true">
                {THEME_SWATCH[th].map((c) => (
                  <i key={c} style={{ background: c }} />
                ))}
              </span>
              <span className="theme-tile__name">{t(THEME_LABEL[th])}</span>
              <span className="theme-tile__hint">{t(THEME_HINT[th])}</span>
            </button>
          ))}
        </div>
      </Card>

      <Card title={t('set.language')} icon="info" hint={t('set.languageHint')}>
        <div className="choices" role="radiogroup" aria-label={t('set.language')}>
          {LOCALES.map((l) => (
            <button
              key={l}
              type="button"
              role="radio"
              aria-checked={locale === l}
              className="choice"
              onClick={() => setLocale(l)}
            >
              <span className="choice__title">{LOCALE_LABEL[l]}</span>
            </button>
          ))}
        </div>
      </Card>

      <Card title={t('set.profiles')} icon="shared" hint={t('set.profileCount', { n: profiles.length })}>
        <ul className="list">
          {profiles.map((p) => (
            <li key={p.id} className="list__item">
              <Icon name="self" size={18} />
              <span className="grow">{p.displayName}</span>
              {p.id === profile.id && <span className="chip chip--primary">{t('set.active')}</span>}
            </li>
          ))}
        </ul>
        {profiles.length < 2 && (
          <div className="stack stack--tight" style={{ marginTop: 'var(--space-3)' }}>
            <Field label={t('set.addPartner')} hint={t('set.addPartnerHint')}>
              {(p) => (
                <input {...p} type="text" value={newProfileName} onChange={(e) => setNewProfileName(e.target.value)} />
              )}
            </Field>
            <button
              className="btn btn--ghost"
              disabled={!newProfileName.trim()}
              onClick={async () => {
                const active = profile.id
                await createProfile({ displayName: newProfileName, stage: profile.stage })
                localStorage.setItem('temudua.activeProfile', active)
                setNewProfileName('')
                await refresh()
                setMessage(t('set.profileAdded'))
              }}
            >{t('set.addProfile')}
            </button>
          </div>
        )}
      </Card>

      <Card
        title={t('set.holidays')}
        icon="calendar"
        hint={t('set.holidaysHint')}
      >
        <input
          type="file"
          accept="application/json,.json"
          aria-label={t('set.importHolidays')}
          onChange={async (e) => {
            const f = e.target.files?.[0]
            if (!f) return
            setError(null)
            try {
              const r = await importPack(await f.text())
              setMessage(t('set.holidaysUpdated', { year: r.year, count: r.count }))
            } catch (err) {
              setError(err instanceof Error ? err.message : t('set.holidaysFailed'))
            }
          }}
        />
      </Card>

      {/* Pairing happens *here*, not behind a link: connecting a second phone
          is a setup task, and one more navigation step was most of the reason
          nobody found it. The full screen is still one tap away for the relay
          settings and the QR fallback. */}
      <PairPanel />
      <Card title={t('set.syncCard')} icon="shared" hint={t('set.syncHint')}>
        <Link to="/sinkron" className="btn btn--ghost btn--block">
          <Icon name="shared" size={18} />
          {t('set.openSync')}
        </Link>
      </Card>

      <Card title={t('set.privacyCard')} icon="shield">
        <Link to="/privasi" className="btn btn--ghost btn--block">
          <Icon name="shield" size={18} />{t('set.openPrivacy')}
        </Link>
      </Card>

      {/* Sample data sits directly above the reset, on purpose: anyone who
          loads it is one card away from the button that clears it. */}
      <Card title={t('demo.title')} icon="date" hint={t('demo.hint')}>
        <div className="stack stack--tight">
          {demoOn ? (
            <>
              <p className="banner">
                <Icon name="info" size={18} />
                {t('demo.loadedNote')}
              </p>
              <button
                className="btn btn--ghost btn--block"
                disabled={demoBusy}
                onClick={() => void removeDemo()}
              >
                <Icon name="close" size={18} />
                {demoBusy ? t('demo.working') : t('demo.remove')}
              </button>
            </>
          ) : (
            <>
              <p className="card__hint">{t('demo.what')}</p>
              <button
                className="btn btn--teal btn--block"
                disabled={demoBusy}
                onClick={() => void addDemo()}
              >
                <Icon name="plus" size={18} />
                {demoBusy ? t('demo.working') : t('demo.load')}
              </button>
              <p className="disclaimer">{t('demo.safe')}</p>
            </>
          )}
        </div>
      </Card>

      <LockSettings />

      <Card title={t('set.wipe')} icon="close" hint={t('set.wipeHint')}>
        <p className="card__hint">{t('set.wipeWhen')}</p>
        <button
          className="btn btn--danger btn--block"
          style={{ marginTop: 'var(--space-2)' }}
          onClick={() => setConfirmWipe(true)}
        >
          <Icon name="close" size={18} />
          {t('set.wipe')}
        </button>
      </Card>

      <p className="card__hint">
        {t('set.footer')}
      </p>

      <Sheet open={confirmWipe} onClose={() => setConfirmWipe(false)} title={t('set.wipeConfirm')}>
        <div className="stack">
          <p className="banner banner--danger">{t('set.wipeWarning')}
          </p>
          <Field label={t('set.wipeType')}>
            {(p) => <input {...p} type="text" value={wipeText} onChange={(e) => setWipeText(e.target.value)} />}
          </Field>
          <button className="btn btn--danger btn--block" disabled={wipeText !== t('set.wipeWord')} onClick={wipe}>{t('set.wipeGo')}
          </button>
          <button className="btn btn--ghost btn--block" onClick={() => setConfirmWipe(false)}>
            {t('common.cancel')}
          </button>
        </div>
      </Sheet>
    </div>
  )
}
